open_pack <- function(pack_type) {
  probs <- if (pack_type == 1) rep(0.2, 5) else
    c(0.3, 0.3, 0.3, 0.05, 0.05)
  sample(LETTERS[1:5], 1, replace = TRUE, prob = probs)
}

